import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f: string) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font: string) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font: string) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type ComponentNameProps = Record<string, any>;

// Utility for front-facing orthographic projection
const isoProject = (x: number, y: number, z: number) => {
  const angle = Math.PI / 6; // 30 degrees tilt forward
  const cosA = Math.cos(angle);
  const sinA = Math.sin(angle);
  return {
    x: x, // Straight-on view
    y: y * cosA - z * sinA,
  };
};

const toPoints = (points: { x: number; y: number }[]) =>
  points.map((p) => `${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(" ");

const mapCharToId = (char: string): string | null => {
  const c = char.toLowerCase();
  if (/^[a-z0-9]$/.test(c)) return c;
  const map: Record<string, string> = {
    " ": "spc",
    "-": "min",
    "=": "eq",
    "[": "lbr",
    "]": "rbr",
    "\\": "bsl",
    ";": "col",
    "'": "quo",
    ",": "com",
    ".": "dot",
    "/": "sla",
    "\n": "ent",
  };
  return map[c] || null;
};

type KeycapDef = { id: string; l: string; w: number; t: string };

// Keyboard 60% Layout Definition
const KEYBOARD_LAYOUT: KeycapDef[][] = [
  // Row 0
  [
    { id: "esc", l: "ESC", w: 1, t: "esc" }, { id: "1", l: "1", w: 1, t: "base" },
    { id: "2", l: "2", w: 1, t: "base" }, { id: "3", l: "3", w: 1, t: "base" },
    { id: "4", l: "4", w: 1, t: "base" }, { id: "5", l: "5", w: 1, t: "base" },
    { id: "6", l: "6", w: 1, t: "base" }, { id: "7", l: "7", w: 1, t: "base" },
    { id: "8", l: "8", w: 1, t: "base" }, { id: "9", l: "9", w: 1, t: "base" },
    { id: "0", l: "0", w: 1, t: "base" }, { id: "min", l: "-", w: 1, t: "base" },
    { id: "eq", l: "=", w: 1, t: "base" }, { id: "bsp", l: "BACKSPACE", w: 2, t: "base" }
  ],
  // Row 1
  [
    { id: "tab", l: "TAB", w: 1.5, t: "base" }, { id: "q", l: "Q", w: 1, t: "base" },
    { id: "w", l: "W", w: 1, t: "wasd" }, { id: "e", l: "E", w: 1, t: "base" },
    { id: "r", l: "R", w: 1, t: "base" }, { id: "t", l: "T", w: 1, t: "base" },
    { id: "y", l: "Y", w: 1, t: "base" }, { id: "u", l: "U", w: 1, t: "base" },
    { id: "i", l: "I", w: 1, t: "base" }, { id: "o", l: "O", w: 1, t: "base" },
    { id: "p", l: "P", w: 1, t: "base" }, { id: "lbr", l: "[", w: 1, t: "base" },
    { id: "rbr", l: "]", w: 1, t: "base" }, { id: "bsl", l: "\\", w: 1.5, t: "base" }
  ],
  // Row 2
  [
    { id: "caps", l: "CAPS", w: 1.75, t: "base" }, { id: "a", l: "A", w: 1, t: "wasd" },
    { id: "s", l: "S", w: 1, t: "wasd" }, { id: "d", l: "D", w: 1, t: "wasd" },
    { id: "f", l: "F", w: 1, t: "base" }, { id: "g", l: "G", w: 1, t: "base" },
    { id: "h", l: "H", w: 1, t: "base" }, { id: "j", l: "J", w: 1, t: "base" },
    { id: "k", l: "K", w: 1, t: "base" }, { id: "l", l: "L", w: 1, t: "base" },
    { id: "col", l: ";", w: 1, t: "base" }, { id: "quo", l: "'", w: 1, t: "base" },
    { id: "ent", l: "ENTER", w: 2.25, t: "base" }
  ],
  // Row 3
  [
    { id: "lsft", l: "SHIFT", w: 2.25, t: "base" }, { id: "z", l: "Z", w: 1, t: "base" },
    { id: "x", l: "X", w: 1, t: "base" }, { id: "c", l: "C", w: 1, t: "base" },
    { id: "v", l: "V", w: 1, t: "base" }, { id: "b", l: "B", w: 1, t: "base" },
    { id: "n", l: "N", w: 1, t: "base" }, { id: "m", l: "M", w: 1, t: "base" },
    { id: "com", l: ",", w: 1, t: "base" }, { id: "dot", l: ".", w: 1, t: "base" },
    { id: "sla", l: "/", w: 1, t: "base" }, { id: "rsft", l: "SHIFT", w: 2.75, t: "base" }
  ],
  // Row 4
  [
    { id: "lctl", l: "CTRL", w: 1.25, t: "base" }, { id: "lwin", l: "WIN", w: 1.25, t: "base" },
    { id: "lalt", l: "ALT", w: 1.25, t: "base" }, { id: "spc", l: "", w: 6.25, t: "base" },
    { id: "ralt", l: "ALT", w: 1.25, t: "base" }, { id: "rwin", l: "WIN", w: 1.25, t: "base" },
    { id: "menu", l: "MENU", w: 1.25, t: "base" }, { id: "rctl", l: "CTRL", w: 1.25, t: "base" }
  ]
];

// Icons for the Search Bar
const SearchIcon = () => (
  <svg focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="22" height="22">
    <path fill="#9aa0a6" d="M15.5 14h-.79l-.28-.27A6.471 6.471 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/>
  </svg>
);

const MicIcon = () => (
  <svg focusable="false" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" width="22" height="22">
    <path fill="#4285f4" d="m12 15c1.66 0 3-1.31 3-2.97v-7.02c0-1.66-1.34-3.01-3-3.01s-3 1.34-3 3.01v7.02c0 1.66 1.34 2.97 3 2.97z"/>
    <path fill="#34a853" d="m11 18.08h2v3.92h-2z"/>
    <path fill="#fbbc05" d="m7.05 16.87c-1.27-1.33-2.05-2.8-2.05-4.87h2c0 1.45.56 2.42 1.47 3.38v.32l-1.15 1.18z"/>
    <path fill="#ea4335" d="m12 16.93a4.97 5.25 0 0 1 -3.54 -1.55l-1.41 1.49c1.26 1.34 3.02 2.13 4.95 2.13 3.87 0 6.99-2.92 6.99-7h-1.99c0 2.92-2.24 4.93-5 4.93z"/>
  </svg>
);

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#121214",
  transparentBackground = false,
  durationInSeconds = 8,
  keyboardBodyColor = "#2a2a2e",
  keycapBaseColor = "#3f3f46",
  wasdColor = "#f97316",
  escColor = "#ef4444",
  typingSpeed = 5,
  textToType = "malloy studio",
  keyboardScale = 1.3,
  searchScale = 1,
  keyboardYOffset = 110,
  searchYOffset = 0,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Geometry Constants
  const U = 44; // Unit size
  const GAP = 6;
  const Z_BASE = 20; // Height of keyboard body
  const Z_TRAVEL_MAX = 16; // Normal unpressed key height
  const Z_TRAVEL_MIN = 4; // Pressed key height
  const INDENT = 8; // Keycap top bevel inset
  const B = 14; // Keyboard body bezel

  const kbWidth = 15 * U;
  const kbDepth = 5 * U;

  // Keyboard Body Polygons
  const bodyTopPoints = toPoints([
    isoProject(-B, -B, Z_BASE),
    isoProject(kbWidth + B, -B, Z_BASE),
    isoProject(kbWidth + B, kbDepth + B, Z_BASE),
    isoProject(-B, kbDepth + B, Z_BASE),
  ]);

  const bodyLeftPoints = toPoints([
    isoProject(-B, -B, 0),
    isoProject(-B, kbDepth + B, 0),
    isoProject(-B, kbDepth + B, Z_BASE),
    isoProject(-B, -B, Z_BASE),
  ]);

  const bodyFrontPoints = toPoints([
    isoProject(-B, kbDepth + B, 0),
    isoProject(kbWidth + B, kbDepth + B, 0),
    isoProject(kbWidth + B, kbDepth + B, Z_BASE),
    isoProject(-B, kbDepth + B, Z_BASE),
  ]);

  const shadowPoints = toPoints([
    isoProject(-B - 25, -B - 25, -10),
    isoProject(kbWidth + B + 25, -B - 25, -10),
    isoProject(kbWidth + B + 25, kbDepth + B + 25, -10),
    isoProject(-B - 25, kbDepth + B + 25, -10),
  ]);

  // Unified Typing Logic
  const safeText = textToType.length > 0 ? textToType : " ";
  const framesPerKey = typingSpeed > 0 ? fps / typingSpeed : Infinity;
  const totalKeys = typingSpeed > 0 ? Math.floor(frame / framesPerKey) : 0;
  const activeIndex = typingSpeed > 0 && totalKeys < safeText.length ? totalKeys : -1;
  const activeChar = activeIndex >= 0 ? safeText[activeIndex] : null;
  const activeKeyId = activeChar ? mapCharToId(activeChar) : null;
  const progressWithinKey = typingSpeed > 0 ? (frame % framesPerKey) / framesPerKey : 0;

  // Search Bar Display Text Calculation (Synced to key down action)
  let displayedText = "";
  if (typingSpeed > 0) {
    if (totalKeys >= safeText.length) {
      displayedText = safeText;
    } else {
      const showCurrentChar = progressWithinKey > 0.5;
      const charsToShow = totalKeys + (showCurrentChar ? 1 : 0);
      displayedText = safeText.substring(0, charsToShow);
    }
  }

  // Blinking cursor synced to FPS
  const showCursor = frame % Math.floor(fps * 0.8) < Math.floor(fps * 0.4);

  // Search Bar Dropdown Animation
  const searchBarSpring = spring({
    frame: Math.max(0, frame - 15), // Slight delay before drop down
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  
  // Calculate vertical alignment parameters to perfectly center the entire composition
  const searchRestingY = height / 2 - 250 + searchYOffset; 
  const searchStartY = searchRestingY - 60;
  
  const searchBarTranslateY = interpolate(searchBarSpring, [0, 1], [searchStartY, searchRestingY]);
  const searchBarOpacity = interpolate(searchBarSpring, [0, 1], [0, 1]);

  // Pre-calculate Keys
  const renderKeys = useMemo(() => {
    const output: React.ReactNode[] = [];
    
    KEYBOARD_LAYOUT.forEach((row, rowIndex) => {
      let currentX = 0;
      const currentY = rowIndex * U;

      row.forEach((key) => {
        const id = key.id;
        const color =
          key.t === "wasd" ? wasdColor : key.t === "esc" ? escColor : keycapBaseColor;

        const x1 = currentX + GAP / 2;
        const y1 = currentY + GAP / 2;
        const x2 = currentX + key.w * U - GAP / 2;
        const y2 = currentY + U - GAP / 2;

        const tx1 = x1 + INDENT;
        const ty1 = y1 + INDENT;
        const tx2 = x2 - INDENT;
        const ty2 = y2 - INDENT;

        // Sequence Typing Logic
        let pressVal = 0;
        if (key.id === activeKeyId && typingSpeed > 0) {
          // Sine wave for smooth depression and release within the key's allotted time
          pressVal = Math.sin(progressWithinKey * Math.PI);
        }
        
        const zTravel = interpolate(pressVal, [0, 1], [Z_TRAVEL_MAX, Z_TRAVEL_MIN], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const zTop = Z_BASE + zTravel;

        const topPoints = toPoints([
          isoProject(tx1, ty1, zTop),
          isoProject(tx2, ty1, zTop),
          isoProject(tx2, ty2, zTop),
          isoProject(tx1, ty2, zTop),
        ]);

        const leftPoints = toPoints([
          isoProject(x1, y1, Z_BASE),
          isoProject(x1, y2, Z_BASE),
          isoProject(tx1, ty2, zTop),
          isoProject(tx1, ty1, zTop),
        ]);

        const rightPoints = toPoints([
          isoProject(x2, y2, Z_BASE),
          isoProject(x2, y1, Z_BASE),
          isoProject(tx2, ty1, zTop),
          isoProject(tx2, ty2, zTop),
        ]);

        const frontPoints = toPoints([
          isoProject(x1, y2, Z_BASE),
          isoProject(x2, y2, Z_BASE),
          isoProject(tx2, ty2, zTop),
          isoProject(tx1, ty2, zTop),
        ]);

        const centroid = isoProject((tx1 + tx2) / 2, (ty1 + ty2) / 2, zTop);

        output.push(
          <g key={id}>
            {/* Left Face */}
            <polygon points={leftPoints} fill={color} />
            <polygon points={leftPoints} fill="#000000" fillOpacity={0.45} />

            {/* Right Face */}
            <polygon points={rightPoints} fill={color} />
            <polygon points={rightPoints} fill="#000000" fillOpacity={0.45} />

            {/* Front Face */}
            <polygon points={frontPoints} fill={color} />
            <polygon points={frontPoints} fill="#000000" fillOpacity={0.25} />

            {/* Top Face */}
            <polygon points={topPoints} fill={color} />
            <polygon points={topPoints} fill="#ffffff" fillOpacity={0.05} />

            {/* Label */}
            {key.l && (
              <text
                x={centroid.x}
                y={centroid.y}
                fill="#ffffff"
                opacity={key.t === "wasd" || key.t === "esc" ? 0.95 : 0.6}
                fontSize={U * 0.28}
                fontWeight="600"
                fontFamily="Inter"
                textAnchor="middle"
                dominantBaseline="central"
                style={{
                  transition: "none",
                  userSelect: "none"
                }}
              >
                {key.l}
              </text>
            )}
          </g>
        );

        currentX += key.w * U;
      });
    });

    return output;
  }, [activeKeyId, progressWithinKey, typingSpeed, keycapBaseColor, wasdColor, escColor, U, GAP, INDENT, Z_BASE, Z_TRAVEL_MAX, Z_TRAVEL_MIN]);

  // SVG viewBox math to center properly
  const svgScale = keyboardScale;
  const angle = Math.PI / 6;
  
  // Find the exact projected 2D center of the keyboard's 3D bounding box
  const cx = kbWidth / 2;
  const cy = (kbDepth / 2) * Math.cos(angle) - (Z_BASE / 2) * Math.sin(angle);

  // Shift keyboard down to balance with the search bar & logo
  const translateX = width / 2 - cx * svgScale;
  const translateY = height / 2 - cy * svgScale + keyboardYOffset;
  const centerTransform = `translate(${translateX}, ${translateY}) scale(${svgScale})`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <svg width={width} height={height} style={{ overflow: "visible", zIndex: 1 }}>
        <defs>
          <filter id="shadow-blur" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="24" />
          </filter>
        </defs>

        <g transform={centerTransform}>
          {/* Floor Shadow */}
          <polygon points={shadowPoints} fill="#000000" opacity={0.6} filter="url(#shadow-blur)" />

          {/* Keyboard Body - Left Face */}
          <polygon points={bodyLeftPoints} fill={keyboardBodyColor} />
          <polygon points={bodyLeftPoints} fill="#000000" fillOpacity={0.5} />

          {/* Keyboard Body - Front Face */}
          <polygon points={bodyFrontPoints} fill={keyboardBodyColor} />
          <polygon points={bodyFrontPoints} fill="#000000" fillOpacity={0.3} />

          {/* Keyboard Body - Top Face */}
          <polygon points={bodyTopPoints} fill={keyboardBodyColor} />

          {/* Keycaps */}
          {renderKeys}
        </g>
      </svg>

      {/* Google Search Container (Logo + Search Bar) */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: "50%",
          transform: `translate(-50%, ${searchBarTranslateY}px) scale(${searchScale})`,
          transformOrigin: "top center",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          zIndex: 10,
          opacity: searchBarOpacity,
          transition: "none",
        }}
      >
        <img 
          src="https://upload.wikimedia.org/wikipedia/commons/2/2f/Google_2015_logo.svg" 
          alt="Google"
          style={{ width: 200, marginBottom: 32 }}
        />
        
        <div
          style={{
            width: 580,
            height: 48,
            backgroundColor: "#ffffff",
            borderRadius: 24,
            boxShadow: "0 1px 6px rgba(32,33,36,0.28)",
            display: "flex",
            alignItems: "center",
            padding: "0 16px 0 20px",
            fontFamily: "Inter, sans-serif",
          }}
        >
          <SearchIcon />
          <div
            style={{
              flex: 1,
              marginLeft: 16,
              fontSize: 18,
              color: "#202124",
              display: "flex",
              alignItems: "center",
              whiteSpace: "pre",
            }}
          >
            {displayedText}
            <span style={{ opacity: showCursor ? 1 : 0, color: "#202124", marginLeft: 1 }}>|</span>
          </div>
          <MicIcon />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;